#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENTS 64
#define STORAGE_KEY_LEN 32
#define NONCE_LEN 12
#define TAG_LEN 16
#define MAX_MSG 4096
#define WS_PORT 8443
#define HTTP_PORT 8080

typedef struct {
    int fd;
    char session_token[65];
    unsigned char storage_key[STORAGE_KEY_LEN];
    int authenticated;
    char origin[256];
} client_t;

static client_t clients[MAX_CLIENTS];
static pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;
static const char *allowed_origins[] = {"https://app.example.com", "https://admin.example.com", NULL};

int encrypt_storage(const unsigned char *key, const unsigned char *plaintext,
                    int pt_len, unsigned char *ciphertext, unsigned char *tag) {
    unsigned char nonce[NONCE_LEN];
    if (RAND_bytes(nonce, NONCE_LEN) != 1)
        return -1;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx)
        return -1;
    int rc = -1;
    int len;
    int ct_len = 0;
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, nonce) != 1)
        goto done;
    if (EVP_EncryptUpdate(ctx, ciphertext + NONCE_LEN, &len, plaintext, pt_len) != 1)
        goto done;
    ct_len = len;
    if (EVP_EncryptFinal_ex(ctx, ciphertext + NONCE_LEN + len, &len) != 1)
        goto done;
    ct_len += len;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, tag) != 1)
        goto done;
    memcpy(ciphertext, nonce, NONCE_LEN);
    rc = ct_len + NONCE_LEN;
done:
    EVP_CIPHER_CTX_free(ctx);
    return rc;
}

int validate_origin(const char *origin) {
    if (origin == NULL || strlen(origin) == 0)
        return 0; /* Reject empty origin - require explicit origin */
    for (int i = 0; allowed_origins[i] != NULL; i++) {
        if (strcmp(origin, allowed_origins[i]) == 0)
            return 1;
    }
    return 0;
}

/* Validate that a session token is safe to embed in a file path.
   Rejects empty tokens and anything containing path separators or
   non-alphanumeric characters to prevent path traversal (CWE-22). */
int is_valid_session_token(const char *token) {
    if (token == NULL)
        return 0;
    size_t len = strlen(token);
    if (len == 0 || len > 64)
        return 0;
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)token[i];
        if (!isalnum(c) && c != '-' && c != '_')
            return 0;
    }
    return 1;
}

int parse_ws_handshake(const char *request, char *origin_out, char *token_out) {
    const char *origin_hdr = strstr(request, "Origin: ");
    if (origin_hdr) {
        origin_hdr += 8;
        const char *end = strstr(origin_hdr, "\r\n");
        if (end) {
            size_t len = end - origin_hdr;
            if (len < 255) {
                memcpy(origin_out, origin_hdr, len);
                origin_out[len] = '\0';
            }
        }
    } else {
        origin_out[0] = '\0';
    }
    const char *cookie_hdr = strstr(request, "Cookie: ");
    if (cookie_hdr) {
        const char *sess = strstr(cookie_hdr, "session=");
        if (sess) {
            sess += 8;
            const char *end = sess;
            while (*end && *end != ';' && *end != '\r') end++;
            size_t len = end - sess;
            if (len < 64) {
                memcpy(token_out, sess, len);
                token_out[len] = '\0';
            }
        }
    }
    return 0;
}

void handle_ws_upgrade(int client_fd, const char *request) {
    char origin[256] = {0};
    char token[65] = {0};
    parse_ws_handshake(request, origin, token);

    if (!validate_origin(origin)) {
        const char *reject = "HTTP/1.1 403 Forbidden\r\n\r\n";
        write(client_fd, reject, strlen(reject));
        close(client_fd);
        return;
    }

    pthread_mutex_lock(&clients_lock);
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (clients[i].fd == 0) {
            clients[i].fd = client_fd;
            strncpy(clients[i].session_token, token, 64);
            clients[i].session_token[64] = '\0';
            strncpy(clients[i].origin, origin, 255);
            clients[i].origin[255] = '\0';
            clients[i].authenticated = (strlen(token) > 0) ? 1 : 0;
            if (RAND_bytes(clients[i].storage_key, STORAGE_KEY_LEN) != 1) {
                /* Fail safely: do not leave a predictable/uninitialized key */
                clients[i].fd = 0;
                clients[i].authenticated = 0;
                pthread_mutex_unlock(&clients_lock);
                const char *reject = "HTTP/1.1 500 Internal Server Error\r\n\r\n";
                write(client_fd, reject, strlen(reject));
                close(client_fd);
                return;
            }
            break;
        }
    }
    pthread_mutex_unlock(&clients_lock);

    const char *accept = "HTTP/1.1 101 Switching Protocols\r\n"
                         "Upgrade: websocket\r\n"
                         "Connection: Upgrade\r\n\r\n";
    write(client_fd, accept, strlen(accept));
}

void handle_storage_write(client_t *client, const char *data, int data_len) {
    /* Reject unsafe session tokens to prevent path traversal (CWE-22) */
    if (!is_valid_session_token(client->session_token))
        return;
    unsigned char ciphertext[MAX_MSG];
    unsigned char tag[TAG_LEN];
    int ct_len = encrypt_storage(client->storage_key, (unsigned char*)data,
                                 data_len, ciphertext, tag);
    if (ct_len < 0)
        return;
    /* Store encrypted data - simplified for demo */
    char filename[128];
    snprintf(filename, sizeof(filename), "/var/ws_storage/%s.enc", client->session_token);
    FILE *f = fopen(filename, "wb");
    if (f) {
        fwrite(ciphertext, 1, ct_len, f);
        fwrite(tag, 1, TAG_LEN, f);
        fclose(f);
    }
}

void *client_handler(void *arg) {
    int fd = *(int*)arg;
    free(arg);
    char buf[MAX_MSG];
    int n = read(fd, buf, MAX_MSG - 1);
    if (n <= 0) { close(fd); return NULL; }
    buf[n] = '\0';
    if (strstr(buf, "Upgrade: websocket")) {
        handle_ws_upgrade(fd, buf);
    }
    return NULL;
}

int main(void) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(WS_PORT),
                               .sin_addr.s_addr = INADDR_ANY};
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 128);
    while (1) {
        int *client_fd = malloc(sizeof(int));
        *client_fd = accept(server_fd, NULL, NULL);
        pthread_t tid;
        pthread_create(&tid, NULL, client_handler, client_fd);
        pthread_detach(tid);
    }
    return 0;
}
